import heapq

def n_linear(m, n):
    U = {1}
    heap = [1]

    for _ in range(n):
        x = heapq.heappop(heap)
        for y in m:
            next_element = x * y + 1
            if next_element not in U:
                U.add(next_element)
                heapq.heappush(heap, next_element)

    return list(sorted(U))[n]

