def exchange_sort(sequence):
    from collections import Counter

    # Count occurrences of each key value
    count = Counter(sequence)

    # Expected positions for each key value
    expected_positions = {7: 0, 8: count[7], 9: count[7] + count[8]}

    # Calculate the number of swaps needed
    swaps = 0
    current_positions = {7: 0, 8: count[7], 9: count[7] + count[8]}

    for key in [7, 8, 9]:
        for _ in range(count[key]):
            if current_positions[key] != expected_positions[key]:
                swaps += 1
                current_positions[key] += 1

    return swaps

