def to_chinese_numeral(n):
    digit_map = {
        0: '零', 1: '一', 2: '二', 3: '三', 4: '四',
        5: '五', 6: '六', 7: '七', 8: '八', 9: '九'
    }
    place_map = {
        0: '', 1: '十', 2: '百', 3: '千', 4: '万'
    }

    def process_number(num):
        if num == 0:
            return '零'
        result = []
        is_zero = False
        for i, digit in enumerate(str(num)):
            digit = int(digit)
            if digit == 0:
                if not is_zero:
                    result.append(digit_map[digit])
                    is_zero = True
            else:
                if is_zero:
                    result.append('零')
                    is_zero = False
                if i > 0 and digit == 1 and result[-1] == place_map[1]:
                    result.pop()
                result.append(digit_map[digit] + place_map[i])
        return ''.join(result)

    if n < 0:
        return '负' + to_chinese_numeral(-n)
    elif n == 0:
        return '零'

    integer_part, decimal_part = str(n).split('.')
    integer_result = process_number(int(integer_part))
    decimal_result = process_number(int(decimal_part)) if decimal_part != '0' else ''

    if decimal_result:
        return integer_result + '点' + decimal_result
    else:
        return integer_result

def to_chinese_numeral(n):
    digit_map = {
        '0': '零', '1': '一', '2': '二', '3': '三', '4': '四',
        '5': '五', '6': '六', '7': '七', '8': '八', '9': '九'
    }
    unit_map = ['', '十', '百', '千', '万']

    def single_digit_to_chinese(digit):
        return digit_map[digit]

    def number_to_chinese(num):
        if num == '0':
            return '零'
        chinese_num = ''
        i = 0
        zero_flag = False
        while i < len(num):
            if num[i] == '0':
                if not zero_flag:
                    chinese_num += '零'
                    zero_flag = True
            else:
                if zero_flag:
                    chinese_num += '零'
                    zero_flag = False
                chinese_num += single_digit_to_chinese(num[i]) + unit_map[len(num) - i - 1]
            i += 1
        return chinese_num

    if n == 0:
        return '零'

    if n < 0:
        return '负' + number_to_chinese(str(n)[1:])

    whole, decimal = str(n).split('.')
    whole_chinese = number_to_chinese(whole)
    decimal_chinese = number_to_chinese(decimal)

    if decimal_chinese == '零':
        return whole_chinese
    else:
        return whole_chinese + '点' + decimal_chinese

def total_inc_dec(x):
    if x == 0:
        return 1
    dp = [[0, 0] for _ in range(x + 1)]
    dp[1][0] = 10  # All single-digit numbers are increasing
    dp[1][1] = 10  # All single-digit numbers are decreasing

    for i in range(2, x + 1):
        dp[i][0] = sum(dp[j][1] for j in range(i))  # Increasing numbers
        dp[i][1] = sum(dp[j][0] for j in range(i))  # Decreasing numbers

    return sum(dp[i][0] + dp[i][1] for i in range(1, x + 1))

def total_inc_dec(x):
    if x == 0:
        return 1

    n = 10 ** x
    dp_inc = [[0] * 10 for _ in range(n + 1)]
    dp_dec = [[0] * 10 for _ in range(n + 1)]

    for i in range(10):
        dp_inc[1][i] = 1
        dp_dec[1][i] = 1

    for i in range(2, n + 1):
        for j in range(10):
            dp_inc[i][j] = sum(dp_inc[i-1][k] for k in range(j, 10))
            dp_dec[i][j] = sum(dp_dec[i-1][k] for k in range(j))

    total = sum(dp_inc[n]) + sum(dp_dec[n])
    return total
